    dates_data = json.loads(r['dates_json'] or '{}')
    flights[r['flight_id']] = {
        'flight_id': r['flight_id'], 'origin': r['origin'], 'destination': r['destination'],
        'dep': r['departure_time'], 'arr': r['arrival_time'], 'dates': dates_data,
    }
conn.close()

available_dates = ['2026-09-10', '2026-09-15', '2026-09-20', '2026-09-25', '2026-10-01', '2026-10-05']
airports = ['JFK', 'LAX', 'SFO', 'SEA', 'LAS', 'SAN', 'MIA']

# Collect unique routes and deduplicate by cheapest economy option per route
routes = {}
for date in available_dates:
    for origin in airports:
        for destination in airports:
            if origin == destination:
                continue
            from_origin = [f for f in flights.values() 
                           if f['origin'] == origin and date in f['dates'] 
                           and f['dates'][date].get('status') == 'available' and f['dep'] is not None]
            for f1 in from_origin:
                hub = f1['destination']
                if hub == origin or hub == destination:
                    continue
                from_hub = [f for f in flights.values()
                            if f['origin'] == hub and f['destination'] == destination
                            and date in f['dates'] and f['dates'][date].get('status') == 'available'
                            and f['dep'] is not None]
                for f2 in from_hub:
                    try:
                        arr1_h, arr1_m = map(int, f1['arr'].split(':')[:2])
                        dep2_h, dep2_m = map(int, f2['dep'].split(':')[:2])
                        layover = (dep2_h * 60 + dep2_m) - (arr1_h * 60 + arr1_m)
                        if layover >= 30:
                            route_key = f"{origin}-{hub}-{destination}"
                            opt_key = f"{f1['flight_id']}+{f2['flight_id']}"
                            f1p = f1['dates'][date].get('prices', {})
                            f2p = f2['dates'][date].get('prices', {})
                            f1s = f1['dates'][date].get('available_seats', {})
                            f2s = f2['dates'][date].get('available_seats', {})

                            if route_key not in routes:
                                routes[route_key] = {}
                            if opt_key not in routes[route_key]:
                                routes[route_key][opt_key] = {
                                    'leg1_id': f1['flight_id'], 'leg1_route': f"{f1['origin']} → {f1['destination']}",
                                    'leg1_dep': f1['dep'], 'leg1_arr': f1['arr'],
                                    'hub': hub, 'layover': layover,
                                    'leg2_id': f2['flight_id'], 'leg2_route': f"{f2['origin']} → {f2['destination']}",
                                    'leg2_dep': f2['dep'], 'leg2_arr': f2['arr'],
                                    'dates': [], 'prices': {},
                                }
                            routes[route_key][opt_key]['dates'].append(date)

                            # Combine prices for this date
                            combined = {}
                            for cabin in ['basic_economy', 'economy', 'business']:
                                if cabin in f1p and cabin in f2p:
                                    combined[cabin] = f1p[cabin] + f2p[cabin]
                            routes[route_key][opt_key]['prices'][date] = combined
                    except (ValueError, TypeError):
                        continue

# Print compact summary
for route_key, options in sorted(routes.items()):
    print(f"\n=== ROUTE: {route_key.replace('-', ' → ')} ===")
    for i, (opt_key, opt) in enumerate(options.items(), 1):
        unique_dates = sorted(set(opt['dates']))
        layover_h = opt['layover'] // 60
        layover_m = opt['layover'] % 60
        print(f"\n  Option {i}: {opt['leg1_id']} + {opt['leg2_id']}")
        print(f"    Leg 1: {opt['leg1_route']}  Dep {opt['leg1_dep']} → Arr {opt['leg1_arr']}")
        print(f"    Leg 2: {opt['leg2_route']}  Dep {opt['leg2_dep']} → Arr {opt['leg2_arr']}")
        print(f"    Layover at {opt['hub']}: {layover_h}h {layover_m}m")
        print(f"    Available dates: {', '.join(unique_dates)}")
        # Show price range (all dates same since same flights)
        sample_prices = list(opt['prices'].values())[0] if opt['prices'] else {}
        if sample_prices:
            price_parts = [f"{k}: ${v}" for k,v in sorted(sample_prices.items())]
            print(f"    Combined prices: {' | '.join(price_parts)}")
